// Drug Sample Creation Function
async createDrugSample(ctx, ...args) {
    if (args.length !== 14) {
        throw new Error("Invalid number of arguments. Expecting 14");
    }

    const SampleId = args[0];

    // --- Invoke chaincode to check if the drug sample already exists ---
    const checkArgs = ["GetSampleStatus", SampleId];
    const sampleExistsResponse = await ctx.stub.invokeChaincode("genericdata", checkArgs, "mychannel");

    const sampleExists = sampleExistsResponse.payload.toString();
    if (sampleExists === "Exists") {
        throw new Error(`Drug sample with ID ${SampleId} already exists.`);
    }

    const drugsample = {
        DrugName: args[1],
        DrugType: args[2],
        Price: args[3],
        ChemicalName: args[4],
        Nature: args[5],
        Condition: args[6],
        Specialization: args[7],
        Ulabel: args[8],
        SidesEffects: args[9],
        Storage: args[10],
        GovernmentApproval: args[11],
        Validity: args[12],
        Doc_Type: "Drug_Sample",
        SentApprovalDate: args[13],
    };

    // --- Invoke chaincode to store the drug sample ---
    const putArgs = ["PutDrugSample", SampleId, JSON.stringify(drugsample)];
    await ctx.stub.invokeChaincode("genericdata", putArgs, "mychannel");

    return drugsample;
}

