async createDrugTestingReport(ctx, ...args) {
    if (args.length !== 6) {
        throw new Error("Invalid number of arguments. Expecting 6");
    }

    const DrugId = args[0];
    const ReportId = `TestReport-${DrugId}`;

    // --- Get the drug data using chaincode invoke ---
    const getDrugArgs = ["GetDrugData", DrugId];
    const drugResponse = await ctx.stub.invokeChaincode("genericdata", getDrugArgs, "mychannel");

    if (!drugResponse.payload || drugResponse.payload.length === 0) {
        throw new Error("Cannot Find Drug");
    }

    const drug = JSON.parse(drugResponse.payload.toString());

    // --- Check if testing report already exists ---
    const getReportArgs = ["GetDrugData", ReportId];
    const existingReportResponse = await ctx.stub.invokeChaincode("genericdata", getReportArgs, "mychannel");

    if (!existingReportResponse.payload || existingReportResponse.payload.length === 0) {
        // --- No existing report, create new one ---
        const TestReport = buildTestReport(drug, args);

        // Add hash and approval date
        const reportStr = JSON.stringify(TestReport);
        const Hash = crypto.createHash("sha1").update(reportStr).digest("hex");
        TestReport.Hash = Hash;
        TestReport.SentApprovalDate = drug.SentApprovalDate;

        // --- Put report and update drug record using chaincode invoke ---
        await ctx.stub.invokeChaincode("genericdata", ["PutDrugData", ReportId, JSON.stringify(TestReport)], "mychannel");
        drug.Doc_Type = "Drug_Testing_Report";
        await ctx.stub.invokeChaincode("genericdata", ["PutDrugData", DrugId, JSON.stringify(drug)], "mychannel");

        return TestReport;
    } else {
        // --- Existing report found, check re-submission eligibility ---
        const drugPDC = JSON.parse(existingReportResponse.payload.toString());
        const cc1Args = ["checkDuration", drugPDC.SentApprovalDate, drug.SentApprovalDate];
        const durationCheckResponse = await ctx.stub.invokeChaincode("druglogic", cc1Args, "mychannel");

        if (durationCheckResponse.payload.toString() !== "Passed") {
            throw new Error("Manufacture can't resend drug sample before 6 months");
        }

        // --- Create and store new report ---
        const TestReport = buildTestReport(drug, args);

        const reportStr = JSON.stringify(TestReport);
        const Hash = crypto.createHash("sha1").update(reportStr).digest("hex");
        TestReport.Hash = Hash;
        TestReport.SentApprovalDate = drug.SentApprovalDate;

        await ctx.stub.invokeChaincode("genericdata", ["PutDrugData", ReportId, JSON.stringify(TestReport)], "mychannel");
        drug.Doc_Type = "Drug_Testing_Report";
        await ctx.stub.invokeChaincode("genericdata", ["PutDrugData", DrugId, JSON.stringify(drug)], "mychannel");

        return TestReport;
    }
}

// 🔧 Helper Function
function buildTestReport(drug, args) {
    const agency = args[1];
    const validAgencies = [
        "Central Drugs Testing Laboratory",
        "Central Drugs Laboratory",
        "Regional Drugs Testing Laboratory",
        "National Institute Of Biologicals"
    ];

    if (!validAgencies.includes(agency)) {
        throw new Error("Invalid Drug Testing Agency");
    }

    return {
        DrugName: drug.DrugName,
        DrugType: drug.DrugType,
        Storage: drug.Storage,
        ChemicalName: drug.ChemicalName,
        Nature: drug.Nature,
        Ulabel: drug.Ulabel,
        Doc_Type: "Drug_Testing_Report",
        TestingAuthority: agency,
        ProcessValidation: args[2],
        CleaningValidation: args[3],
        EquipmentValidation: args[4],
        AnalyticalMethodsValidation: args[5]
    };
}

