async function createDrugApproval(ctx, ...args) {
    // Parameters Checking
    if (args.length !== 4) {
        throw new Error("Invalid no. of args. Expecting 4");
    }

    const drugId = args[0];
    const approvingAgency = args[1];

    // Approving Authority Checking
    if (approvingAgency !== "CDSCO") {
        throw new Error("Only Government Agency can Approve Drug");
    }

    // --- Fetch Test Report ---
    const reportId = "TestReport-" + drugId;
    const getReportArgs = ["GetDrugData", reportId];
    const reportResponse = await ctx.stub.invokeChaincode("genericdata", getReportArgs, "mychannel");
    const drugAsBytes = reportResponse.payload;

    if (!drugAsBytes || drugAsBytes.length === 0) {
        throw new Error("Cannot Find Drug Report");
    }

    const drug = JSON.parse(drugAsBytes.toString());

    // --- Verify Hash Integrity ---
    const originalHash = drug.Hash;
    delete drug.Hash; // Remove hash field before recalculating
    const generatedHash = crypto.createHash("sha1").update(JSON.stringify(drug)).digest("hex");

    if (originalHash !== generatedHash) {
        throw new Error("Forged Test Report Found");
    }

    // --- Retrieve Drug Data ---
    const getDrugArgs = ["GetDrugData", drugId];
    const drugResponse = await ctx.stub.invokeChaincode("genericdata", getDrugArgs, "mychannel");
    const drugBytes = drugResponse.payload;

    if (!drugBytes || drugBytes.length === 0) {
        throw new Error(`${drugId} Drug does not exist`);
    }

    const drugData = JSON.parse(drugBytes.toString());

    // --- Update Drug Data ---
    drugData.GovernmentApprovalAuthority = approvingAgency;
    drugData.MaxDosage = args[2];
    drugData.GovernmentApproval = args[3];
    drugData.Doc_Type = "Government_Approval";
    drugData.GovernmentHash = crypto.createHash("sha1").update(JSON.stringify(drugData)).digest("hex");

    // --- Store Updated Drug Data ---
    const putDrugArgs = ["PutDrugSample", drugId, JSON.stringify(drugData)];
    await ctx.stub.invokeChaincode("genericdata", putDrugArgs, "mychannel");

    // --- Update and Store Test Report ---
    drug.Doc_Type = "Government_Approval";
    const putReportArgs = ["PutDrugSample", reportId, JSON.stringify(drug)];
    await ctx.stub.invokeChaincode("genericdata", putReportArgs, "mychannel");
}

